// Hand-written `koa` stub for the flowatlas fixture suite.
//
// Koa itself declares no route. It is here because it is where the middleware
// in front of a whole router is installed, and reading the router without the
// application would read every route and miss the only guard in the repository.

export interface Context {
  params: Record<string, string>;
  request: { body: unknown };
  status: number;
  body: unknown;
  get(header: string): string;
}

export type Next = () => Promise<void>;

export type Middleware = (ctx: Context, next: Next) => unknown;

declare class Application {
  use(middleware: Middleware): Application;
  listen(port: number): unknown;
}

export default Application;
